-- +goose Up
CREATE TABLE IF NOT EXISTS public.auth_metadata (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    provider text NOT NULL,
    subject text NOT NULL,
    last_login_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS public.password_reset_tokens (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    token_hash text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    request_ip text
);

CREATE TABLE IF NOT EXISTS public.subscription_plans (
    id uuid NOT NULL,
    name text NOT NULL,
    max_file_size_mb bigint NOT NULL,
    max_files_per_job bigint NOT NULL,
    retention_days bigint NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS public.user_sessions (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    access_token_hash text NOT NULL,
    refresh_token_hash text,
    prev_refresh_token_hash text,
    access_expires_at timestamp with time zone NOT NULL,
    refresh_expires_at timestamp with time zone,
    rotated_at timestamp with time zone,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS public.users (
    id uuid NOT NULL,
    email text NOT NULL,
    full_name text,
    phone text,
    country text,
    image_url text,
    password_hash text NOT NULL,
    plan_name text DEFAULT 'free'::text NOT NULL,
    role text DEFAULT 'user'::text NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_user_role CHECK ((role = ANY (ARRAY['user'::text, 'admin'::text, 'super-admin'::text])))
);

